            low, high = SCALARS[name]
        else:
            raise QueryError("unknown function %s" % name_tok.value)
        if len(args) < low or (high is not None and len(args) > high):
            raise QueryError("wrong number of arguments to %s" % name)
        if name in AGGREGATES:
            return ("agg", name, args[0])
        return ("func", name, tuple(args))


def map_children(node, fn):
    """Return ``node`` with ``fn`` applied to each of its direct subexpressions."""
    kind = node[0]
    if kind in ("lit", "name", "col"):
        return node
    if kind == "bin":
        return ("bin", node[1], fn(node[2]), fn(node[3]))
    if kind == "in":
        return ("in", fn(node[1]), tuple(fn(x) for x in node[2]), node[3])
    if kind == "func":
        return ("func", node[1], tuple(fn(x) for x in node[2]))
    if kind == "agg":
        return ("agg", node[1], None if node[2] is None else fn(node[2]))
    # neg, and, or, not, isnull, between, like: subexpressions are the tuple
    # elements, flags are bools.
    return (kind,) + tuple(fn(x) if isinstance(x, tuple) else x for x in node[1:])


def children(node):
    found = []
    map_children(node, lambda child: found.append(child) or child)
    return found


def contains_aggregate(node):
    return node[0] == "agg" or any(contains_aggregate(c) for c in children(node))

