"""Tokenizer and parser for minisql queries.

Expressions are parsed into nested tuples whose first element names the
node kind:

    ('lit', type_name, value)        literal (type_name keeps 1, 1.0, TRUE apart)
    ('name', lowered, raw)           column reference, before resolution
    ('col', index)                   column reference, after resolution
    ('neg', expr)
    ('bin', op, left, right)         + - * / || = != < <= > >=
    ('and', left, right)
    ('or', left, right)
    ('not', expr)
    ('isnull', expr, negated)
    ('in', expr, (item, ...), negated)
    ('between', expr, low, high, negated)
    ('like', expr, pattern, negated)
    ('func', NAME, (arg, ...))       scalar function
    ('agg', NAME, arg_or_None)       aggregate; None for COUNT(*)

Tuples compare structurally, which is how GROUP BY expressions are matched.
"""

import re
from collections import namedtuple

from ._errors import QueryError

KEYWORDS = {
    "SELECT", "DISTINCT", "FROM", "WHERE", "GROUP", "BY", "HAVING", "ORDER",
    "ASC", "DESC", "LIMIT", "OFFSET", "AS", "AND", "OR", "NOT", "IS", "NULL",
    "IN", "BETWEEN", "LIKE", "TRUE", "FALSE",
}

AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}

# Function name -> (min args, max args); None means unbounded.
SCALARS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

COMPARISON_OPS = {"=", "!=", "<>", "<", "<=", ">", ">="}

Token = namedtuple("Token", "kind value start end")

_TOKEN_RE = re.compile(
    r"""
    (?P<ws>\s+)
  | (?P<float>[0-9]+\.[0-9]*|\.[0-9]+)
  | (?P<int>[0-9]+)
  | (?P<name>[^\W\d]\w*)
  | (?P<qname>"(?:[^"]|"")*")
  | (?P<str>'(?:[^']|'')*')
  | (?P<op><>|!=|<=|>=|\|\||[=<>+\-*/(),;])
    """,
    re.VERBOSE,
)


def tokenize(sql):
    tokens = []
    pos = 0
    while pos < len(sql):
        m = _TOKEN_RE.match(sql, pos)
        if not m:
            ch = sql[pos]
            if ch in "'\"":
                raise QueryError("unterminated quoted text at position %d" % pos)
            raise QueryError("unexpected character %r at position %d" % (ch, pos))
        kind = m.lastgroup
        text = m.group()
        start, pos = m.start(), m.end()
        if kind == "ws":
            continue
        if kind in ("int", "float") and pos < len(sql) and re.match(r"[\w.]", sql[pos]):
            raise QueryError("invalid number at position %d" % start)
        if kind == "int":
            value = int(text)
        elif kind == "float":
            value = float(text)
        elif kind == "name":
            if text.upper() in KEYWORDS:
                kind, value = "kw", text.upper()
            else:
                value = text
        elif kind == "qname":
            value = text[1:-1].replace('""', '"')
        elif kind == "str":
            value = text[1:-1].replace("''", "'")
        else:
            value = text
        tokens.append(Token(kind, value, start, pos))
    tokens.append(Token("eof", None, len(sql), len(sql)))
    return tokens


# A parsed output column: expression, AS name (or None), the expression's
# text as written, and whether it was written as a single token.
Column = namedtuple("Column", "expr alias text single")
OrderItem = namedtuple("OrderItem", "expr desc single")
Query = namedtuple(
    "Query",
    "distinct columns table where group_by having order_by limit offset",
)


def parse(sql):
    return _Parser(sql).parse_query()


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers -------------------------------------------------

    @property
    def tok(self):
        return self.tokens[self.pos]

    def peek(self, offset=1):
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def is_kw(self, *words, tok=None):
        tok = tok or self.tok
        return tok.kind == "kw" and tok.value in words

    def is_op(self, *ops, tok=None):
        tok = tok or self.tok
        return tok.kind == "op" and tok.value in ops

    def accept_kw(self, word):
        if self.is_kw(word):
            return self.advance()
        return None

    def accept_op(self, op):
        if self.is_op(op):
            return self.advance()
        return None

    def error(self, expected):
        tok = self.tok
        if tok.kind == "eof":
            found = "end of query"
        else:
            found = repr(self.sql[tok.start:tok.end])
        return QueryError("expected %s but found %s at position %d"
                          % (expected, found, tok.start))

    def expect_kw(self, word):
        if not self.is_kw(word):
            raise self.error(word)
        return self.advance()

    def expect_op(self, op):
        if not self.is_op(op):
            raise self.error("'%s'" % op)
        return self.advance()

    def expect_name(self):
        if self.tok.kind not in ("name", "qname"):
            raise self.error("a name")
        return self.advance().value

    def expect_int(self):
        if self.tok.kind != "int":
            raise self.error("an integer")
        return self.advance().value

    # -- query ---------------------------------------------------------

    def parse_query(self):
        self.expect_kw("SELECT")
        distinct = bool(self.accept_kw("DISTINCT"))
        if self.accept_op("*"):
            columns = None
        else:
            columns = [self.parse_column()]
            while self.accept_op(","):
                columns.append(self.parse_column())
        self.expect_kw("FROM")
        table = self.expect_name()

        where = having = limit = offset = None
        group_by = []
        order_by = []
        if self.accept_kw("WHERE"):
            where = self.parse_expr()
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group_by.append(self.parse_expr())
            while self.accept_op(","):
                group_by.append(self.parse_expr())
        if self.accept_kw("HAVING"):
            having = self.parse_expr()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            order_by.append(self.parse_order_item())
            while self.accept_op(","):
                order_by.append(self.parse_order_item())
        if self.accept_kw("LIMIT"):
            limit = self.expect_int()
            if self.accept_kw("OFFSET"):
                offset = self.expect_int()
        self.accept_op(";")
        if self.tok.kind != "eof":
            raise self.error("end of query")
        return Query(distinct, columns, table, where, group_by, having,
                     order_by, limit, offset)

    def parse_spanned_expr(self):
        """Parse an expression; also return its source text and token count."""
        first = self.pos
        expr = self.parse_expr()
        start = self.tokens[first].start
        end = self.tokens[self.pos - 1].end
        return expr, self.sql[start:end], self.pos - first == 1

    def parse_column(self):
        expr, text, single = self.parse_spanned_expr()
        alias = None
        if self.accept_kw("AS"):
            alias = self.expect_name()
        elif self.tok.kind in ("name", "qname"):
            alias = self.advance().value
        return Column(expr, alias, text, single)

    def parse_order_item(self):
        expr, _, single = self.parse_spanned_expr()
        desc = False
        if self.accept_kw("DESC"):
            desc = True
        else:
            self.accept_kw("ASC")
        return OrderItem(expr, desc, single)

    # -- expressions ---------------------------------------------------

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.accept_kw("OR"):
            left = ("or", left, self.parse_and())
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.accept_kw("AND"):
            left = ("and", left, self.parse_not())
        return left

    def parse_not(self):
        if self.accept_kw("NOT"):
            return ("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        while True:
            if self.is_op(*COMPARISON_OPS):
                op = self.advance().value
                if op == "<>":
                    op = "!="
                left = ("bin", op, left, self.parse_additive())
            elif self.accept_kw("IS"):
                negated = bool(self.accept_kw("NOT"))
                self.expect_kw("NULL")
                left = ("isnull", left, negated)
            elif self.is_kw("IN", "BETWEEN", "LIKE") or (
                self.is_kw("NOT") and self.is_kw("IN", "BETWEEN", "LIKE", tok=self.peek())
            ):
                negated = bool(self.accept_kw("NOT"))
                word = self.advance().value
                if word == "IN":
                    self.expect_op("(")
                    items = [self.parse_expr()]
                    while self.accept_op(","):
                        items.append(self.parse_expr())
                    self.expect_op(")")
                    left = ("in", left, tuple(items), negated)
                elif word == "BETWEEN":
                    low = self.parse_additive()
                    self.expect_kw("AND")
                    high = self.parse_additive()
                    left = ("between", left, low, high, negated)
                else:
                    left = ("like", left, self.parse_additive(), negated)
            else:
                return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.is_op("+", "-", "||"):
            op = self.advance().value
            left = ("bin", op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.is_op("*", "/"):
            op = self.advance().value
            left = ("bin", op, left, self.parse_unary())
        return left

    def parse_unary(self):
        if self.accept_op("-"):
            return ("neg", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        tok = self.tok
        if tok.kind in ("int", "float", "str"):
            self.advance()
            return ("lit", type(tok.value).__name__, tok.value)
        if self.is_kw("NULL", "TRUE", "FALSE"):
            self.advance()
            value = {"NULL": None, "TRUE": True, "FALSE": False}[tok.value]
            return ("lit", type(value).__name__, value)
        if self.accept_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        if tok.kind == "name" and self.is_op("(", tok=self.peek()):
            return self.parse_call()
        if tok.kind in ("name", "qname"):
            self.advance()
            return ("name", tok.value.lower(), tok.value)
        raise self.error("an expression")

    def parse_call(self):
        name_tok = self.advance()
        name = name_tok.value.upper()
        self.expect_op("(")
        if name == "COUNT" and self.accept_op("*"):
            self.expect_op(")")
            return ("agg", name, None)
        args = []
        if not self.is_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        self.expect_op(")")

        if name in AGGREGATES:
            low, high = 1, 1
        elif name in SCALARS:
            low, high = SCALARS[name]
        else:
            raise QueryError("unknown function %s" % name_tok.value)
        if len(args) < low or (high is not None and len(args) > high):
            raise QueryError("wrong number of arguments to %s" % name)
        if name in AGGREGATES:
            return ("agg", name, args[0])
        return ("func", name, tuple(args))


def map_children(node, fn):
    """Return ``node`` with ``fn`` applied to each of its direct subexpressions."""
    kind = node[0]
    if kind in ("lit", "name", "col"):
        return node
    if kind == "bin":
        return ("bin", node[1], fn(node[2]), fn(node[3]))
    if kind == "in":
        return ("in", fn(node[1]), tuple(fn(x) for x in node[2]), node[3])
    if kind == "func":
        return ("func", node[1], tuple(fn(x) for x in node[2]))
    if kind == "agg":
        return ("agg", node[1], None if node[2] is None else fn(node[2]))
    # neg, and, or, not, isnull, between, like: subexpressions are the tuple
    # elements, flags are bools.
    return (kind,) + tuple(fn(x) if isinstance(x, tuple) else x for x in node[1:])


def children(node):
    found = []
    map_children(node, lambda child: found.append(child) or child)
    return found


def contains_aggregate(node):
    return node[0] == "agg" or any(contains_aggregate(c) for c in children(node))

