        raise QueryError("unknown table %s" % name) from None
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table %s: %s" % (name, e)) from None
    if not records:
        raise QueryError("table %s has no header" % name)
    header = records[0]
    rows = []
    for record in records[1:]:
        if len(record) > len(header):
            raise QueryError("table %s has a row with too many fields" % name)
        record = record + [""] * (len(header) - len(record))
        rows.append([_convert(field) for field in record])
    return header, rows


# -- values ---------------------------------------------------------------

def _kind(value):
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    return "string"


def _is_number(value):
    return _kind(value) == "number"


def _text(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def _compare(a, b):
    """Compare two non-NULL values; return -1, 0, or 1."""
    ka, kb = _kind(a), _kind(b)
    if ka != kb:
        raise QueryError("cannot compare %s with %s" % (ka, kb))
    return (a > b) - (a < b)


def _value_key(value):
    """A hashable key under which equal values (1 and 1.0) coincide but
    values of different kinds (1 and TRUE) don't."""
    return (_kind(value), value)


def _check_bool(value, what):
    if value is not None and not isinstance(value, bool):
        raise QueryError("%s needs a boolean, not %s" % (what, _kind(value)))
    return value


def _arith(op, a, b):
    if a is None or b is None:
        return None
    if not (_is_number(a) and _is_number(b)):
        raise QueryError("cannot apply %s to %s and %s" % (op, _kind(a), _kind(b)))
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if b == 0:
        return None
    return a / b


def _compare_op(op, a, b):
    if a is None or b is None:
        return None
    c = _compare(a, b)
    return {
        "=": c == 0, "!=": c != 0, "<": c < 0,
        "<=": c <= 0, ">": c > 0, ">=": c >= 0,
    }[op]


def _and(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _not(a):
    return None if a is None else not a


@functools.lru_cache(maxsize=256)
def _like_regex(pattern):
    parts = []
    for ch in pattern:
        if ch == "%":
            parts.append(".*")
        elif ch == "_":
            parts.append(".")
        else:
            parts.append(re.escape(ch))
    return re.compile("".join(parts), re.DOTALL)


def _round(x, n):
    try:
        if n is None:
            return int(Decimal(repr(x)).quantize(Decimal(1), ROUND_HALF_UP))
        exp = Decimal(1).scaleb(-n)
        return float(Decimal(repr(x)).quantize(exp, ROUND_HALF_UP))
    except (InvalidOperation, OverflowError, ValueError):
        raise QueryError("cannot round %r" % x) from None


def _call(name, args):
    if name == "COALESCE":
        for arg in args:
            if arg is not None:
                return arg
        return None
    if any(arg is None for arg in args):
        return None
    if name in ("LOWER", "UPPER", "LENGTH"):
        (s,) = args
        if not isinstance(s, str):
            raise QueryError("%s needs a string, not %s" % (name, _kind(s)))
        if name == "LOWER":
            return s.lower()
        if name == "UPPER":
            return s.upper()
        return len(s)
    x = args[0]
    if not _is_number(x):
        raise QueryError("%s needs a number, not %s" % (name, _kind(x)))
    if name == "ABS":
        return abs(x)
    # ROUND
    if len(args) == 1:
        return _round(x, None)
    n = args[1]
    if _kind(n) != "number" or not isinstance(n, int):
        raise QueryError("ROUND needs an integer number of places")
    return _round(x, n)


def _aggregate(name, values):
    if name == "COUNT":
        return sum(1 for v in values if v is not None)
    values = [v for v in values if v is not None]
    if not values:
        return None
    if name in ("SUM", "AVG"):
        for v in values:
            if not _is_number(v):
                raise QueryError("%s needs numbers, not %s" % (name, _kind(v)))
        total = sum(values)
        return total / len(values) if name == "AVG" else total
    best = values[0]
    for v in values[1:]:
        c = _compare(v, best)
        if (c < 0) if name == "MIN" else (c > 0):
            best = v
    return best


class _Context:
    """What an expression is evaluated against: a row, and for a grouped
    query also the group's rows (``row`` is then the group's first row, or
    None for an empty group)."""

    __slots__ = ("row", "group")

    def __init__(self, row, group=None):
        self.row = row
        self.group = group


def evaluate(node, ctx):
    kind = node[0]
    if kind == "lit":
        return node[2]
    if kind == "col":
        return ctx.row[node[1]]
    if kind == "neg":
        v = evaluate(node[1], ctx)
        if v is None:
            return None
        if not _is_number(v):
            raise QueryError("cannot negate %s" % _kind(v))
        return -v
    if kind == "bin":
        op = node[1]
        a = evaluate(node[2], ctx)
        b = evaluate(node[3], ctx)
        if op == "||":
            if a is None or b is None:
                return None
            return _text(a) + _text(b)
        if op in ("+", "-", "*", "/"):
            return _arith(op, a, b)
        return _compare_op(op, a, b)
    if kind == "and":
        return _and(_check_bool(evaluate(node[1], ctx), "AND"),
                    _check_bool(evaluate(node[2], ctx), "AND"))
    if kind == "or":
        return _or(_check_bool(evaluate(node[1], ctx), "OR"),
                   _check_bool(evaluate(node[2], ctx), "OR"))
    if kind == "not":
        return _not(_check_bool(evaluate(node[1], ctx), "NOT"))
    if kind == "isnull":
        is_null = evaluate(node[1], ctx) is None
        return not is_null if node[2] else is_null
    if kind == "in":
        x = evaluate(node[1], ctx)
        result = False
        for item in node[2]:
            eq = _compare_op("=", x, evaluate(item, ctx))
            if eq:
                result = True
            elif eq is None and result is False:
                result = None
        return _not(result) if node[3] else result
    if kind == "between":
        x = evaluate(node[1], ctx)
        low = evaluate(node[2], ctx)
        high = evaluate(node[3], ctx)
        result = _and(_compare_op("<=", low, x), _compare_op("<=", x, high))
        return _not(result) if node[4] else result
    if kind == "like":
        s = evaluate(node[1], ctx)
        pattern = evaluate(node[2], ctx)
        if s is None or pattern is None:
            return None
        if not (isinstance(s, str) and isinstance(pattern, str)):
            raise QueryError("LIKE needs strings, not %s and %s"
                             % (_kind(s), _kind(pattern)))
        result = _like_regex(pattern).fullmatch(s) is not None
        return not result if node[3] else result
    if kind == "func":
        return _call(node[1], [evaluate(arg, ctx) for arg in node[2]])
    if kind == "agg":
        if node[2] is None:
            return len(ctx.group)
        values = [evaluate(node[2], _Context(row)) for row in ctx.group]
        return _aggregate(node[1], values)
    raise AssertionError("unknown node %r" % (kind,))


# -- query planning -------------------------------------------------------

def _resolve(node, header):
    """Replace column names with column indices."""
    if node[0] == "name":
        for i, column in enumerate(header):
            if column.lower() == node[1]:
                return ("col", i)
        raise QueryError("unknown column %s" % node[2])
    return map_children(node, lambda child: _resolve(child, header))


def _check_no_aggregate(node, where):
    if contains_aggregate(node):
        raise QueryError("aggregates can't be used in %s" % where)


def _check_aggregates_not_nested(node):
    if node[0] == "agg":
        if node[2] is not None:
            _check_no_aggregate(node[2], "another aggregate")
        return
    for child in children(node):
        _check_aggregates_not_nested(child)


def _check_grouped(node, group_by):
    """Check that columns outside aggregates are GROUP BY expressions."""
    if node in group_by or node[0] == "agg":
        return
    if node[0] == "col":
        raise QueryError("column must appear in GROUP BY or be in an aggregate")
    for child in children(node):
        _check_grouped(child, group_by)


def _nulls_first_cmp(a, b):
    if a is None or b is None:
        return (a is not None) - (b is not None)
    return _compare(a, b)


_sort_key = functools.cmp_to_key(_nulls_first_cmp)


def _sort(keyed, descending):
    """Stable-sort (key values, row) pairs; ``descending`` has a flag per key."""
    for i in reversed(range(len(descending))):
        keyed.sort(key=lambda item: _sort_key(item[0][i]), reverse=descending[i])


def run(sql, directory="."):
    query = parse(sql)
    header, table = load_table(directory, query.table)

    def resolve(node):
        return _resolve(node, header)

    # Output columns: (expression, name).
    if query.columns is None:
        outputs = [(("col", i), name) for i, name in enumerate(header)]
    else:
        outputs = []
        for col in query.columns:
            expr = resolve(col.expr)
            if col.alias is not None:
                name = col.alias
            elif col.single and expr[0] == "col":
                name = header[expr[1]]
            else:
                name = col.text
            outputs.append((expr, name))
    names = [name for _, name in outputs]

    where = resolve(query.where) if query.where is not None else None
    group_by = [resolve(e) for e in query.group_by]
    having = resolve(query.having) if query.having is not None else None

    # ORDER BY items: ("output", index, desc) or ("expr", expression, desc).
    order_by = []
    lowered_names = [name.lower() for name in names]
    for item in query.order_by:
        expr = item.expr
        if item.single and expr[0] == "name" and expr[1] in lowered_names:
            order_by.append(("output", lowered_names.index(expr[1]), item.desc))
        elif item.single and expr[0] == "lit" and expr[1] == "int":
            n = expr[2]
            if not 1 <= n <= len(outputs):
                raise QueryError("ORDER BY column %d is out of range" % n)
            order_by.append(("output", n - 1, item.desc))
        else:
            order_by.append(("expr", resolve(expr), item.desc))

    if where is not None:
        _check_no_aggregate(where, "WHERE")
    for expr in group_by:
        _check_no_aggregate(expr, "GROUP BY")
    exprs = [e for e, _ in outputs]
    if having is not None:
        exprs.append(having)
    exprs.extend(e for kind, e, _ in order_by if kind == "expr")
    for expr in exprs:
        _check_aggregates_not_nested(expr)

    grouped = bool(group_by) or any(contains_aggregate(e) for e in exprs)
    if grouped:
        for expr in exprs:
            _check_grouped(expr, group_by)

    # FROM and WHERE.
    rows = table
    if where is not None:
        rows = [row for row in rows
                if _check_bool(evaluate(where, _Context(row)), "WHERE") is True]

    # GROUP BY.
    if not grouped:
        contexts = [_Context(row) for row in rows]
    elif not group_by:
        contexts = [_Context(rows[0] if rows else None, rows)]
    else:
        groups = {}
        for row in rows:
            key = tuple(_value_key(evaluate(e, _Context(row))) for e in group_by)
            groups.setdefault(key, []).append(row)
        contexts = [_Context(group[0], group) for group in groups.values()]

    # HAVING.
    if having is not None:
        contexts = [ctx for ctx in contexts
                    if _check_bool(evaluate(having, ctx), "HAVING") is True]

    # SELECT and DISTINCT.
    results = [(ctx, tuple(evaluate(e, ctx) for e in exprs[:len(outputs)]))
               for ctx in contexts]
    if query.distinct:
        seen = set()
        unique = []
        for ctx, out in results:
            key = tuple(_value_key(v) for v in out)
            if key not in seen:
                seen.add(key)
                unique.append((ctx, out))
        results = unique

    # ORDER BY.
    if order_by:
        keyed = []
        for ctx, out in results:
            values = [out[x] if kind == "output" else evaluate(x, ctx)
                      for kind, x, _ in order_by]
            keyed.append((values, out))
        _sort(keyed, [desc for _, _, desc in order_by])
        out_rows = [out for _, out in keyed]
    else:
        out_rows = [out for _, out in results]

    # LIMIT and OFFSET.
    start = query.offset or 0
    end = None if query.limit is None else start + query.limit
    return Result(names, out_rows[start:end])

"""Query execution: loading tables, evaluating expressions, running queries."""

import csv
import functools
import os
import re
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

from ._errors import QueryError
from ._parser import children, contains_aggregate, map_children, parse

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


class Result:
    """The result of a query: ``columns`` (names) and ``rows`` (tuples)."""

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)


# -- tables ---------------------------------------------------------------

def _convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


def load_table(directory, name):
    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            records = [r for r in csv.reader(f) if r]
    except FileNotFoundError:
        raise QueryError("unknown table %s" % name) from None
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table %s: %s" % (name, e)) from None
    if not records:
        raise QueryError("table %s has no header" % name)
    header = records[0]
    rows = []
    for record in records[1:]:
        if len(record) > len(header):
            raise QueryError("table %s has a row with too many fields" % name)
        record = record + [""] * (len(header) - len(record))
        rows.append([_convert(field) for field in record])
    return header, rows


# -- values ---------------------------------------------------------------

def _kind(value):
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    return "string"


def _is_number(value):
    return _kind(value) == "number"


def _text(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def _compare(a, b):
    """Compare two non-NULL values; return -1, 0, or 1."""
    ka, kb = _kind(a), _kind(b)
    if ka != kb:
        raise QueryError("cannot compare %s with %s" % (ka, kb))
    return (a > b) - (a < b)


def _value_key(value):
    """A hashable key under which equal values (1 and 1.0) coincide but
    values of different kinds (1 and TRUE) don't."""
    return (_kind(value), value)


def _check_bool(value, what):
    if value is not None and not isinstance(value, bool):
        raise QueryError("%s needs a boolean, not %s" % (what, _kind(value)))
    return value


def _arith(op, a, b):
    if a is None or b is None:
        return None
    if not (_is_number(a) and _is_number(b)):
        raise QueryError("cannot apply %s to %s and %s" % (op, _kind(a), _kind(b)))
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if b == 0:
        return None
    return a / b


def _compare_op(op, a, b):
    if a is None or b is None:
        return None
    c = _compare(a, b)
    return {
        "=": c == 0, "!=": c != 0, "<": c < 0,
        "<=": c <= 0, ">": c > 0, ">=": c >= 0,
    }[op]


def _and(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _not(a):
    return None if a is None else not a


@functools.lru_cache(maxsize=256)
def _like_regex(pattern):
    parts = []
    for ch in pattern:
        if ch == "%":
            parts.append(".*")
        elif ch == "_":
            parts.append(".")
        else:
            parts.append(re.escape(ch))
    return re.compile("".join(parts), re.DOTALL)


def _round(x, n):
    if n is not None and n > 400:
        return float(x)  # beyond any float's precision
    if n is not None and n < -400:
        return 0.0
    try:
        with localcontext() as context:
            context.prec = 1000
            if n is None:
                return int(Decimal(repr(x)).quantize(Decimal(1), ROUND_HALF_UP))
            exp = Decimal(1).scaleb(-n)
            return float(Decimal(repr(x)).quantize(exp, ROUND_HALF_UP))
    except (InvalidOperation, OverflowError, ValueError):
        raise QueryError("cannot round %r" % x) from None


def _call(name, args):
    if name == "COALESCE":
        for arg in args:
            if arg is not None:
                return arg
        return None
    if any(arg is None for arg in args):
        return None
    if name in ("LOWER", "UPPER", "LENGTH"):
        (s,) = args
        if not isinstance(s, str):
            raise QueryError("%s needs a string, not %s" % (name, _kind(s)))
        if name == "LOWER":
            return s.lower()
        if name == "UPPER":
            return s.upper()
        return len(s)
    x = args[0]
    if not _is_number(x):
        raise QueryError("%s needs a number, not %s" % (name, _kind(x)))
    if name == "ABS":
        return abs(x)
    # ROUND
    if len(args) == 1:
        return _round(x, None)
    n = args[1]
    if _kind(n) != "number" or not isinstance(n, int):
        raise QueryError("ROUND needs an integer number of places")
    return _round(x, n)


def _aggregate(name, values):
    if name == "COUNT":
        return sum(1 for v in values if v is not None)
    values = [v for v in values if v is not None]
    if not values:
        return None
    if name in ("SUM", "AVG"):
        for v in values:
            if not _is_number(v):
                raise QueryError("%s needs numbers, not %s" % (name, _kind(v)))
        total = sum(values)
        return total / len(values) if name == "AVG" else total
    best = values[0]
    for v in values[1:]:
        c = _compare(v, best)
        if (c < 0) if name == "MIN" else (c > 0):
            best = v
    return best


class _Context:
    """What an expression is evaluated against: a row, and for a grouped
    query also the group's rows (``row`` is then the group's first row, or
    None for an empty group)."""

    __slots__ = ("row", "group")

    def __init__(self, row, group=None):
        self.row = row
        self.group = group


def evaluate(node, ctx):
    kind = node[0]
    if kind == "lit":
        return node[2]
    if kind == "col":
        return ctx.row[node[1]]
    if kind == "neg":
        v = evaluate(node[1], ctx)
        if v is None:
            return None
        if not _is_number(v):
            raise QueryError("cannot negate %s" % _kind(v))
        return -v
    if kind == "bin":
        op = node[1]
        a = evaluate(node[2], ctx)
        b = evaluate(node[3], ctx)
        if op == "||":
            if a is None or b is None:
                return None
            return _text(a) + _text(b)
        if op in ("+", "-", "*", "/"):
            return _arith(op, a, b)
        return _compare_op(op, a, b)
    if kind == "and":
        return _and(_check_bool(evaluate(node[1], ctx), "AND"),
                    _check_bool(evaluate(node[2], ctx), "AND"))
    if kind == "or":
        return _or(_check_bool(evaluate(node[1], ctx), "OR"),
                   _check_bool(evaluate(node[2], ctx), "OR"))
    if kind == "not":
        return _not(_check_bool(evaluate(node[1], ctx), "NOT"))
    if kind == "isnull":
        is_null = evaluate(node[1], ctx) is None
        return not is_null if node[2] else is_null
    if kind == "in":
        x = evaluate(node[1], ctx)
        result = False
        for item in node[2]:
            eq = _compare_op("=", x, evaluate(item, ctx))
            if eq:
                result = True
            elif eq is None and result is False:
                result = None
        return _not(result) if node[3] else result
    if kind == "between":
        x = evaluate(node[1], ctx)
        low = evaluate(node[2], ctx)
        high = evaluate(node[3], ctx)
        result = _and(_compare_op("<=", low, x), _compare_op("<=", x, high))
        return _not(result) if node[4] else result
    if kind == "like":
        s = evaluate(node[1], ctx)
        pattern = evaluate(node[2], ctx)
        if s is None or pattern is None:
            return None
        if not (isinstance(s, str) and isinstance(pattern, str)):
            raise QueryError("LIKE needs strings, not %s and %s"
                             % (_kind(s), _kind(pattern)))
        result = _like_regex(pattern).fullmatch(s) is not None
        return not result if node[3] else result
    if kind == "func":
        return _call(node[1], [evaluate(arg, ctx) for arg in node[2]])
    if kind == "agg":
        if node[2] is None:
            return len(ctx.group)
        values = [evaluate(node[2], _Context(row)) for row in ctx.group]
        return _aggregate(node[1], values)
    raise AssertionError("unknown node %r" % (kind,))


# -- query planning -------------------------------------------------------

def _resolve(node, header):
    """Replace column names with column indices."""
    if node[0] == "name":
        for i, column in enumerate(header):
            if column.lower() == node[1]:
                return ("col", i)
        raise QueryError("unknown column %s" % node[2])
    return map_children(node, lambda child: _resolve(child, header))


def _check_no_aggregate(node, where):
    if contains_aggregate(node):
        raise QueryError("aggregates can't be used in %s" % where)


def _check_aggregates_not_nested(node):
    if node[0] == "agg":
        if node[2] is not None:
            _check_no_aggregate(node[2], "another aggregate")
        return
    for child in children(node):
        _check_aggregates_not_nested(child)


def _check_grouped(node, group_by):
    """Check that columns outside aggregates are GROUP BY expressions."""
    if node in group_by or node[0] == "agg":
        return
    if node[0] == "col":
        raise QueryError("column must appear in GROUP BY or be in an aggregate")
    for child in children(node):
        _check_grouped(child, group_by)


def _nulls_first_cmp(a, b):
    if a is None or b is None:
        return (a is not None) - (b is not None)
    return _compare(a, b)


_sort_key = functools.cmp_to_key(_nulls_first_cmp)


def _sort(keyed, descending):
    """Stable-sort (key values, row) pairs; ``descending`` has a flag per key."""
    for i in reversed(range(len(descending))):
        keyed.sort(key=lambda item: _sort_key(item[0][i]), reverse=descending[i])


def run(sql, directory="."):
    query = parse(sql)
    header, table = load_table(directory, query.table)

    def resolve(node):
        return _resolve(node, header)

    # Output columns: (expression, name).
    if query.columns is None:
        outputs = [(("col", i), name) for i, name in enumerate(header)]
    else:
        outputs = []
        for col in query.columns:
            expr = resolve(col.expr)
            if col.alias is not None:
                name = col.alias
            elif col.single and expr[0] == "col":
                name = header[expr[1]]
            else:
                name = col.text
            outputs.append((expr, name))
    names = [name for _, name in outputs]

    where = resolve(query.where) if query.where is not None else None
    group_by = [resolve(e) for e in query.group_by]
    having = resolve(query.having) if query.having is not None else None

    # ORDER BY items: ("output", index, desc) or ("expr", expression, desc).
    order_by = []
    lowered_names = [name.lower() for name in names]
    for item in query.order_by:
        expr = item.expr
        if item.single and expr[0] == "name" and expr[1] in lowered_names:
            order_by.append(("output", lowered_names.index(expr[1]), item.desc))
        elif item.single and expr[0] == "lit" and expr[1] == "int":
            n = expr[2]
            if not 1 <= n <= len(outputs):
                raise QueryError("ORDER BY column %d is out of range" % n)
            order_by.append(("output", n - 1, item.desc))
        else:
            order_by.append(("expr", resolve(expr), item.desc))

    if where is not None:
        _check_no_aggregate(where, "WHERE")
    for expr in group_by:
        _check_no_aggregate(expr, "GROUP BY")
    exprs = [e for e, _ in outputs]
    if having is not None:
        exprs.append(having)
    exprs.extend(e for kind, e, _ in order_by if kind == "expr")
    for expr in exprs:
        _check_aggregates_not_nested(expr)

    grouped = bool(group_by) or any(contains_aggregate(e) for e in exprs)
    if grouped:
        for expr in exprs:
            _check_grouped(expr, group_by)

    # FROM and WHERE.
    rows = table
    if where is not None:
        rows = [row for row in rows
                if _check_bool(evaluate(where, _Context(row)), "WHERE") is True]

    # GROUP BY.
    if not grouped:
        contexts = [_Context(row) for row in rows]
    elif not group_by:
        contexts = [_Context(rows[0] if rows else None, rows)]
    else:
        groups = {}
        for row in rows:
            key = tuple(_value_key(evaluate(e, _Context(row))) for e in group_by)
            groups.setdefault(key, []).append(row)
        contexts = [_Context(group[0], group) for group in groups.values()]

    # HAVING.
    if having is not None:
        contexts = [ctx for ctx in contexts
                    if _check_bool(evaluate(having, ctx), "HAVING") is True]

    # SELECT and DISTINCT.
    results = [(ctx, tuple(evaluate(e, ctx) for e in exprs[:len(outputs)]))
               for ctx in contexts]
    if query.distinct:
        seen = set()
        unique = []
        for ctx, out in results:
            key = tuple(_value_key(v) for v in out)
            if key not in seen:
                seen.add(key)
                unique.append((ctx, out))
        results = unique

    # ORDER BY.
    if order_by:
        keyed = []
        for ctx, out in results:
            values = [out[x] if kind == "output" else evaluate(x, ctx)
                      for kind, x, _ in order_by]
            keyed.append((values, out))
        _sort(keyed, [desc for _, _, desc in order_by])
        out_rows = [out for _, out in keyed]
    else:
        out_rows = [out for _, out in results]

    # LIMIT and OFFSET.
    start = query.offset or 0
    end = None if query.limit is None else start + query.limit
    return Result(names, out_rows[start:end])

